name: Semantic Version Bumper Tests

on:
  push:
  pull_request:
  workflow_dispatch:

permissions:
  contents: read

jobs:
  unit-tests:
    name: Unit Tests
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: oven-sh/setup-bun@v1
        with:
          bun-version: latest

      - name: Install dependencies
        run: bun install

      - name: Run unit tests
        run: bun test version-bumper.test.ts
        shell: bash

  workflow-structure-tests:
    name: Workflow Structure Tests
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Validate actionlint
        run: actionlint .github/workflows/semantic-version-bumper.yml

      - name: Check workflow file exists
        run: test -f .github/workflows/semantic-version-bumper.yml || exit 1
        shell: bash

      - name: Check required script files
        run: |
          test -f version-bumper.ts || exit 1
          test -f cli.ts || exit 1
        shell: bash

  integration-tests:
    name: Integration Tests with Act
    runs-on: ubuntu-latest
    needs: [unit-tests]
    steps:
      - uses: actions/checkout@v4
      - uses: oven-sh/setup-bun@v1
        with:
          bun-version: latest

      - name: Install dependencies
        run: bun install
        shell: bash

      - name: Create test runner script
        run: |
          cat > run-act-tests.ts << 'EOF'
          import * as fs from "fs";
          import * as path from "path";
          import { testFixtures, createMockGitRepo, cleanupMockRepo } from "./test-fixtures";

          async function runActTest(fixture: typeof testFixtures[0]): Promise<boolean> {
            const tempDir = `/tmp/act-test-${Date.now()}-${Math.random()}`;
            console.log(`\n${"=".repeat(60)}`);
            console.log(`Testing: ${fixture.name}`);
            console.log(`Expected version: ${fixture.currentVersion} -> ${fixture.expectedVersion}`);
            console.log(`${"=".repeat(60)}`);

            try {
              createMockGitRepo(tempDir, fixture);

              const proc = Bun.spawnSync(["act", "push", "--rm", "-W", ".github/workflows/semantic-version-bumper.yml"], {
                cwd: tempDir,
                stdio: ["ignore", "pipe", "pipe"],
              });

              const stdout = new TextDecoder().decode(proc.stdout || new Uint8Array());
              const stderr = new TextDecoder().decode(proc.stderr || new Uint8Array());
              const output = stdout + "\n" + stderr;

              fs.appendFileSync("act-result.txt", `\n${"=".repeat(60)}\nTest: ${fixture.name}\n${"=".repeat(60)}\n${output}\n`);

              if (proc.exitCode !== 0) {
                console.error(`❌ Act failed for ${fixture.name} with exit code ${proc.exitCode}`);
                return false;
              }

              if (!output.includes("Job succeeded")) {
                console.error(`❌ Job did not succeed for ${fixture.name}`);
                return false;
              }

              console.log(`✓ ${fixture.name} passed`);
              return true;
            } catch (error) {
