  const fixes = commits.filter((c) => c.startsWith("fix:"));
  const breaking = commits.filter((c) => c.includes("BREAKING CHANGE"));

  let changelog = `## [${newVersion}] - ${new Date().toISOString().split("T")[0]}\n`;

